499	func (h *Handler) ServeHTTP(w http.ResponseWriter, r *http.Request, next caddyhttp.Handler) error {
500		repl := r.Context().Value(caddy.ReplacerCtxKey).(*caddy.Replacer)
501	
502		// prepare the request for proxying; this is needed only once
503		clonedReq, err := h.prepareRequest(r, repl)
504		if err != nil {
505			return caddyhttp.Error(http.StatusInternalServerError,
506				fmt.Errorf("preparing request for upstream round-trip: %v", err))
507		}
508	
509		// websocket over http2 or http3 if extended connect is enabled, assuming backend doesn't support this, the request will be modified to http1.1 upgrade
510		// Both use the same upgrade mechanism: server advertizes extended connect support, and client sends the pseudo header :protocol in a CONNECT request
511		// The quic-go http3 implementation also puts :protocol in r.Proto for CONNECT requests (quic-go/http3/headers.go@70-72,185,203)
512		// TODO: once we can reliably detect backend support this, it can be removed for those backends
513		if (r.ProtoMajor == 2 && r.Method == http.MethodConnect && r.Header.Get(":protocol") == "websocket") ||
514			(r.ProtoMajor == 3 && r.Method == http.MethodConnect && r.Proto == "websocket") {
515			clonedReq.Header.Del(":protocol")
516			// keep the body for later use. http1.1 upgrade uses http.NoBody
517			caddyhttp.SetVar(clonedReq.Context(), "extended_connect_websocket_body", clonedReq.Body)
518			clonedReq.Body = http.NoBody
519			clonedReq.Method = http.MethodGet
520			clonedReq.Header.Set("Upgrade", "websocket")
521			clonedReq.Header.Set("Connection", "Upgrade")
522			key := make([]byte, 16)
523			_, randErr := rand.Read(key)
524			if randErr != nil {
525				return randErr
526			}
527			clonedReq.Header["Sec-WebSocket-Key"] = []string{base64.StdEncoding.EncodeToString(key)}
528		}
529	
530		// we will need the original headers and Host value if
531		// header operations are configured; this is so that each
532		// retry can apply the modifications, because placeholders
533		// may be used which depend on the selected upstream for
534		// their values
535		reqHost := clonedReq.Host
536		reqHeader := clonedReq.Header
537	
538		// If the request contained a body, wrap it in io.NopCloser
539		// to prevent Go's transport from closing it on dial errors.
540		// cloneRequest does a shallow copy, so clonedReq.Body and
541		// r.Body share the same io.ReadCloser — a dial-failure Close()
542		// would kill the original body for all subsequent retry
543		// attempts or subsequent handlers. The real body is closed by
544		// the HTTP server when the handler returns.
545		//
546		// If the body was already fully buffered (via request_buffers),
547		// we also extract the buffer so the retry loop can replay it
548		// from the beginning on each attempt. (see #6259, #7546, #7713)
549		var bufferedReqBody *bytes.Buffer
550		if clonedReq.Body != nil {
551			if reqBodyBuf, ok := clonedReq.Body.(bodyReadCloser); ok && reqBodyBuf.body == nil && reqBodyBuf.buf != nil {
552				bufferedReqBody = reqBodyBuf.buf
553				reqBodyBuf.buf = nil
554				clonedReq.Body = io.NopCloser(bytes.NewReader(bufferedReqBody.Bytes()))
555				defer func() {
556					bufferedReqBody.Reset()
557					bufPool.Put(bufferedReqBody)
558				}()
559			} else {
560				clonedReq.Body = &bodyNopCloserIfNotRead{ReadCloser: clonedReq.Body}
561			}
562		}
563	
564		start := time.Now()
565		defer func() {
566			// total proxying duration, including time spent on LB and retries
567			repl.Set("http.reverse_proxy.duration", time.Since(start))
568			repl.Set("http.reverse_proxy.duration_ms", time.Since(start).Seconds()*1e3) // multiply seconds to preserve decimal (see #4666)
569		}()
570	
571		// in the proxy loop, each iteration is an attempt to proxy the request,
572		// and because we may retry some number of times, carry over the error
573		// from previous tries because of the nuances of load balancing & retries
574		//
575		// triedUpstreams tracks the upstreams that have already been selected for
576		// this request and failed before producing a final response. It is scoped
577		// to this single client request only: it ensures a retry lands on a
578		// different upstream (selection policies such as random or round_robin do
579		// not guarantee that on their own, and "first" would otherwise re-select
580		// the same first upstream forever), and never leaks state between
581		// requests.
582		var proxyErr error
583		var retries int
584		triedUpstreams := make(map[string]struct{})
585		for {
586			// a new attempt must never be started once the whole-attempt time
587			// limit has elapsed; this gate is the authoritative deadline check
588			// for starting attempts (tryAgain caps the wait between them)
589			if retries > 0 && h.LoadBalancing.TryDuration > 0 &&
590				time.Since(start) >= time.Duration(h.LoadBalancing.TryDuration) {
591				break
592			}
593	
594			// if the request body was buffered (and only the entire body, hence no body
595			// set to read from after the buffer), make reading from the body idempotent
596			// and reusable, so if a backend partially or fully reads the body but then
597			// produces an error, the request can be repeated to the next backend with
598			// the full body (retries should only happen for idempotent requests) (see #6259)
599			if bufferedReqBody != nil {
600				clonedReq.Body = io.NopCloser(bytes.NewReader(bufferedReqBody.Bytes()))
601			}
602	
603			var done bool
604			done, proxyErr = h.proxyLoopIteration(clonedReq, r, w, proxyErr, start, retries, repl, reqHeader, reqHost, next, triedUpstreams)
605			if done {
606				break
607			}
608			if h.VerboseLogs {
609				var lbWait time.Duration
610				if h.LoadBalancing != nil {
611					lbWait = time.Duration(h.LoadBalancing.TryInterval)
612				}
613				if c := h.logger.Check(zapcore.DebugLevel, "retrying"); c != nil {
614					c.Write(zap.Error(proxyErr), zap.Duration("after", lbWait))
615				}
616			}
617			retries++
618		}
619	
620		// number of retries actually performed
621		repl.Set("http.reverse_proxy.retries", retries)
622	
623		if proxyErr != nil {
624			return statusError(proxyErr)
625		}
626	
627		return nil
628	}
629	
630	// proxyLoopIteration implements an iteration of the proxy loop. Despite the enormous amount of local state
631	// that has to be passed in, we brought this into its own method so that we could run defer more easily.
632	// It returns true when the loop is done and should break; false otherwise. The error value returned should
633	// be assigned to the proxyErr value for the next iteration of the loop (or the error handled after break).
634	func (h *Handler) proxyLoopIteration(r *http.Request, origReq *http.Request, w http.ResponseWriter, proxyErr error, start time.Time, retries int,
635		repl *caddy.Replacer, reqHeader http.Header, reqHost string, next caddyhttp.Handler, triedUpstreams map[string]struct{},
636	) (bool, error) {
637		// get the updated list of upstreams
638		upstreams := h.Upstreams
639		if h.DynamicUpstreams != nil {
640			if retries > 0 {
641				// after a failure (and thus during a retry), give dynamic upstream modules an opportunity
642				// to purge their relevant cache entries so we don't keep retrying bad upstreams
643				if cachingDynamicUpstreams, ok := h.DynamicUpstreams.(CachingUpstreamSource); ok {
644					if err := cachingDynamicUpstreams.ResetCache(r); err != nil {
645						if c := h.logger.Check(zapcore.ErrorLevel, "failed clearing dynamic upstream source's cache"); c != nil {
646							c.Write(zap.Error(err))
647						}
648					}
649				}
650			}
651			dUpstreams, err := h.DynamicUpstreams.GetUpstreams(r)
652			if err != nil {
653				if c := h.logger.Check(zapcore.ErrorLevel, "failed getting dynamic upstreams; falling back to static upstreams"); c != nil {
654					c.Write(zap.Error(err))
655				}
656			} else {
657				upstreams = dUpstreams
658				for _, dUp := range dUpstreams {
659					h.provisionUpstream(dUp, true)
660				}
