180			}
181			if resp, err := tlsClient.Get(p.httpsURL + "/ok"); err == nil {
182				io.Copy(io.Discard, resp.Body)
183				resp.Body.Close()
184				tlsOK = resp.StatusCode == http.StatusOK
185			}
186			if httpOK && tlsOK {
187				ready = true
188				break
189			}
190			time.Sleep(25 * time.Millisecond)
191		}
192		if !ready {
193			p.dumpLogsAndKill()
194			t.Fatalf("caddy on %s never became ready", p.httpAddr)
195		}
196		return p
197	}
198	
199	func (p *caddyProc) dumpLogsAndKill() {
200		_ = p.kill()
201		p.t.Logf("caddy logs:\n%s", p.logs.String())
202	}
203	
204	// stop cleanly stops the instance with SIGTERM, waits for it to be fully
205	// reaped with a successful exit code, and verifies the listen address has
206	// been released (it can be bound again). Once this returns there is no
207	// half-alive instance and no previous process can still answer requests.
208	func (p *caddyProc) stop() {
209		p.t.Helper()
210		if p.cmd.ProcessState != nil {
211			return
212		}
213		if err := p.cmd.Process.Signal(syscall.SIGTERM); err != nil {
214			p.t.Fatalf("signal caddy: %v\n%s", err, p.logs.String())
215		}
216		done := make(chan error, 1)
217		go func() { done <- p.cmd.Wait() }()
218		select {
219		case err := <-done:
220			if err != nil {
221				p.t.Fatalf("caddy did not shut down cleanly: %v\n%s", err, p.logs.String())
222			}
223		case <-time.After(20 * time.Second):
224			p.dumpLogsAndKill()
225			p.t.Fatalf("caddy did not exit within 20s of SIGTERM")
226		}
227		if !p.cmd.ProcessState.Exited() || p.cmd.ProcessState.ExitCode() != 0 {
228			p.t.Fatalf("caddy exit state: %s, want exit code 0", p.cmd.ProcessState)
229		}
230	
231		// The address must be releasable and rebindable immediately: bind it from
232		// this test, then release it for the next instance.
233		ln, err := net.Listen("tcp", p.httpAddr)
234		if err != nil {
235			p.t.Fatalf("listen address %s not released after stop: %v", p.httpAddr, err)
236		}
237		_ = ln.Close()
238	
239		if p.t.Failed() {
240			p.t.Logf("caddy logs:\n%s", p.logs.String())
241		}
242	}
243	
244	func (p *caddyProc) kill() error {
245		if p.cmd.ProcessState != nil {
246			return nil
247		}
248		_ = p.cmd.Process.Signal(syscall.SIGKILL)
249		return p.cmd.Wait()

